THOUGHT: Based on my analysis, I can see that there are two places where pointer handling for nested structs is missing:
1. In `getScanArgsForNestedStructs` function where there's a TODO comment
2. In `buildSelectQueryForNestedStructs` function where it doesn't handle pointer types

Let me create a simple test to verify the issue first:

```bash
cat <<'EOF' > test_nested_pointer.go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/vingarcia/ksql"
	"github.com/vingarcia/ksql/sqldialect"
	"github.com/vingarcia/ksql/adapters/ksqlite3"
)

type User struct {
	ID   int64  `ksql:"id"`
	Name string `ksql:"name"`
}

type Address struct {
	UserID int64  `ksql:"user_id"`
	Street string `ksql:"street"`
}

type UserWithAddress struct {
	User    User    `tablename:"users"`
	Address Address `tablename:"addresses"`
}

func main() {
	ctx := context.Background()
	db, err := ksqlite3.New(ctx, ":memory:", ksql.Config{})
	if err != nil {
		log.Fatal(err)
	}

	// Create tables
	_, err = db.DB.ExecContext(ctx, `
		CREATE TABLE users (
			id INTEGER PRIMARY KEY,
			name TEXT
		);
	`)
	if err != nil {
		log.Fatal(err)
	}

	_, err = db.DB.ExecContext(ctx, `
		CREATE TABLE addresses (
			user_id INTEGER,
			street TEXT,
			FOREIGN KEY(user_id) REFERENCES users(id)
		);
	`)
	if err != nil {
		log.Fatal(err)
	}

	// Insert test data
	_, err = db.DB.ExecContext(ctx, `INSERT INTO users (id, name) VALUES (1, 'John')`)
	if err != nil {
		log.Fatal(err)
	}

	_, err = db.DB.ExecContext(ctx, `INSERT INTO addresses (user_id, street) VALUES (1, '123 Main St')`)
	if err != nil {
		log.Fatal(err)
	}

	// Try to query with nested struct
	var userWithAddr UserWithAddress
	err = db.QueryOne(ctx, &userWithAddr, "FROM users u JOIN addresses a ON u.id = a.user_id WHERE u.id = ?", 1)
	if err != nil {
		fmt.Printf("Error querying nested struct: %v\n", err)
	} else {
		fmt.Printf("Success: %+v\n", userWithAddr)
	}
}
EOF
```

